  insert into public.brands (name, website, description, country, status) values ('Qure Skincare', 'https://qureskincare.com', 'US skincare brand selling science-backed at-home devices and serums, known for the Micro-Infusion System and the Q-Rejuvalight Pro LED mask; it runs a tiered creator affiliate program powered by Social Snowball that a platform case study credits with $380K of affiliate revenue in one quarter.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'skincare'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Social Snowball (own program)', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://qureskincare.com/pages/affiliate-terms-and-conditions.', 'https://qureskincare.com/pages/affiliate-terms-and-conditions', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Qure Skincare Affiliate Program (Social Snowball)', 'https://qureskincare.com/pages/affiliate-terms-and-conditions', null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://qureskincare.com/pages/affiliate-terms-and-conditions', 'brand_site', 'affiliate_program', 'Qure''s own affiliate program terms page (fetched) states the Qure Skincare Affiliate Marketing Program is powered by Social Snowball, that affiliates receive a unique referral code and/or link, and that commissions are earned on qualifying sales directly attributable to the code or link; the terms do not publish a commission rate, so commission_rate is recorded as null.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.socialsnowball.io/post/qure-affiliate-program-case-study', 'affiliate_directory', 'affiliate_program', 'Social Snowball''s case study of the Qure program (fetched) reports Qure replaced flat commissions with tiered incentives, generated almost $380,000 from the affiliate program in one quarter (75% of its influencer marketing revenue), pays out automatically through Tremendous, and quotes Qure''s affiliate manager by name. No rate or earnings-cap statement is published in either source, so the cap is unknown; no creator count is published, so saturation is also unknown.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://qureskincare.com', 'brand_site', 'brand_overview', 'The brand''s own homepage (fetched) presents its Micro-Infusion System and Q-Rejuvalight Pro LED Mask, names co-founder Kristina Orlic-Edmonds, and features a panel of named dermatologists and doctors endorsing the products.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 18, 8, 8, 9, 4, '{"compensation": "A tiered structure exists and the brand says it wants to offer affiliates the highest commission possible, but no rate is published anywhere fetched, so compensation cannot be scored higher.", "contact_access": "The program terms are published on the brand''s own site; no public affiliate contact email was found on the pages checked.", "credibility": "Established device brand with named dermatologist endorsements on its own homepage and a detailed third-party platform case study of its program.", "niche_fit": "LED masks and micro-infusion devices are premium, highly demonstrable UGC skincare products with strong before/after content potential.", "opportunity_availability": "Open affiliate program with published terms on the brand''s own site.", "ugc_evidence": "The program is creator-first by design: it drove 75% of the brand''s influencer revenue in the case-study quarter, uses tracked creator links instead of leaked discount codes, and the brand actively recruits content creators."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Tarte', 'https://tartecosmetics.com', 'US cosmetics brand founded on Amazonian-clay formulas, known for the Shape Tape concealer and cruelty-free color cosmetics; affiliate directories consistently report its network program at 8% per sale.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'beauty'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Partnerize (reported)', 8, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://getlasso.co/affiliate/tarte/.', 'https://getlasso.co/affiliate/tarte/', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Tarte Affiliate Program (Partnerize, reported)', 'https://getlasso.co/affiliate/tarte/', null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/tarte/', 'affiliate_directory', 'affiliate_program', 'The Lasso directory (fetched) lists the Tarte affiliate program at 8% per sale across all products; Admitad''s beauty program roundup and Tapfiliate''s beauty list independently give the same 8% figure, and Brandid''s creator comparison table gives around 8% with a 7-day cookie.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.whichprogram.com/en/country/us?category=beauty', 'affiliate_directory', 'commission_rate', 'WhichProgram''s network listing names Partnerize as the network for the tarte Cosmetics affiliate offer at 8% with a 7-day cookie and application required; other roundups variously name Partnerize/Ascend, FlexOffers or Rakuten, so the network is recorded as Partnerize (reported). Shopper''s ''up to 15%'' is a ceiling figure and is not the base rate. No earnings-cap statement was found, so the cap is unknown; no creator count is published, so saturation is also unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 14, 12, 8, 9, 5, '{"compensation": "A consistent 8% per sale across several directories is a fair mid-tier rate for a high-converting brand, though the reported 7-day cookie is short.", "contact_access": "Join route is the network listing via directories; no public partnerships email was found.", "credibility": "One of the largest US indie-born color brands with global retail distribution; program terms rest on consistent directory reporting.", "niche_fit": "Viral concealer and color cosmetics are a core short-video UGC category for tutorials, shades and wear tests.", "opportunity_availability": "Open network program with application, listed across multiple directories.", "ugc_evidence": "The brand is a long-standing influencer-collaboration heavyweight and creator roundups single it out for short-video creators, though it publishes no own creator program page in the sources checked."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('MO Clinical', 'https://www.moclinical.com', 'US clinical skincare brand whose own affiliate page runs a tiered program for spa partners and content creators, paying 8% at the Bronze tier rising to 15% at Gold, with monthly cash payouts via Stripe.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'skincare'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Own program (brand direct)', 8, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://www.moclinical.com/affiliate-program.', 'https://www.moclinical.com/affiliate-program', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'MO Clinical Affiliate Program (brand direct)', 'https://www.moclinical.com/affiliate-program', null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.moclinical.com/affiliate-program', 'brand_site', 'affiliate_program', 'The brand''s own affiliate page (fetched) publishes commission tiers that auto-promote on lifetime attributed sales: Bronze 8% for all approved affiliates, Silver 12% at $5,000+ lifetime sales, Gold 15% at $20,000+, with a 10% buyer discount code, 30-day attribution, a $50 minimum payout and monthly cash payouts via Stripe. The page explicitly recruits three audiences including content creators (''Beauty bloggers, TikTok, YouTube''), and states applications are reviewed within 48 hours and the program is US affiliates only at launch. The recorded rate is the 8% Bronze base.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.moclinical.com/affiliate-program', 'brand_site', 'commission_cap', 'No earnings-cap or ''unlimited earnings'' statement appears on the fetched program page, so the cap is recorded as unknown. No creator count is published, so saturation is also unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 14, 13, 9, 8, 3, '{"compensation": "A published 8% base with transparent auto-promotion to 12% and 15% is a solid structure for a small brand; the $50 minimum payout is standard.", "contact_access": "Applications run through the brand''s own affiliate page with a stated 48-hour review; no public partnerships email is published.", "credibility": "Full tier terms are published on the brand''s own page, but the brand is small with limited independent coverage in the sources checked.", "niche_fit": "Clinical skincare fits routine and results content, though the range is narrower and more treatment-led than mass skincare.", "opportunity_availability": "Open application on the brand''s own page; US affiliates only at launch.", "ugc_evidence": "The program page names content creators as a core audience alongside spa partners, with branded codes at the Gold tier."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('The Indie Earth', 'https://theindieearth.in', 'Indian natural skincare and haircare brand whose Indie Circle creator program pays 10% commission at the Member tier rising to 25% at Inner Circle, with free monthly products, a personal code and links, and UPI or bank payouts from Rs 1,000.', 'India', 'published') returning id into bid;
