  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'The Indie Earth Indie Circle Creator Program (brand direct)', 'https://theindieearth.in/partners/', null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://theindieearth.in/partners/', 'brand_site', 'affiliate_program', 'The brand''s own Indie Circle creator program page (fetched) publishes four tiers based on delivered orders in the last 30 days: Member 10% for everyone, Insider 15% at 10+ orders, Icon 20% at 30+ orders and Inner Circle 25% at 75+ orders, with 2-8 free products a month by tier, a personal code and custom links, a 30-day click window, commission on the amount paid after discounts, and payouts to UPI or bank from Rs 1,000 once commission unlocks 15 days after delivery. The recorded rate is the 10% Member base.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://theindieearth.in/partners/', 'brand_site', 'commission_cap', 'No earnings-cap or ''unlimited earnings'' statement appears on the fetched program page, so the cap is recorded as unknown. No creator count is published, so saturation is also unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 17, 14, 8, 8, 3, '{"compensation": "10% base rising to 25% at published order thresholds, plus 2-8 free products a month, is a generous published structure for a brand of this size.", "contact_access": "Applications run through the brand''s own program page with a stated two-working-day reply; no public partnerships email is published on the page.", "credibility": "Full tier and payout terms are published on the brand''s own page; the brand is India-focused with limited independent coverage in the sources checked.", "niche_fit": "Natural skincare and haircare with creator content kits and product guides fits routine and review UGC well.", "opportunity_availability": "Open application for creators on Instagram, YouTube or any platform, personally reviewed.", "ugc_evidence": "A purpose-built creator program with content kits, approved captions, free review products and per-link analytics is strong creator evidence."}'::jsonb);
