  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Awin', 4, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://ui.awin.com/merchant-profile/16364.', 'https://ui.awin.com/merchant-profile/16364', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'CurrentBody Affiliate Program (Awin)', 'https://ui.awin.com/merchant-profile/16364', null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/16364', 'brand_site', 'affiliate_program', 'CurrentBody''s own Awin merchant profile for the US & Canada program (fetched) describes the brand as the pioneering online destination for home-use health and beauty technology, listing categories including Health, Beauty, Facial Products, Hair, Skincare, Beauty Devices and Anti-Aging.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.affiliategraph.ai/programs/currentbody', 'affiliate_directory', 'commission_rate', 'Affiliate Graph''s network-listing summary (fetched) reports a 4% default commission for CurrentBody with category rates of 20% on radio-frequency, wellness, LED and hair-growth products, 6% on Dermalux and 4% on laser hair removal, across Awin, Connexity, Digidip, Skimlinks and Webgains; the brand''s Dutch Awin program terms reproduced on affi.io likewise show percentage groups (new customer 6%, existing customer 4%, brand groups 4-8%, voucher 2%). The recorded rate is the 4% default. Lasso''s ''$8 per sale'' figure conflicts with every percentage source and is treated as that directory''s artifact. No earnings-cap statement was found, so the cap is unknown; no creator count is published, so saturation is also unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 12, 11, 8, 9, 5, '{"compensation": "The 4% default is low, but published category rates reach 20% on the highest-value device lines and order values are premium; exact groups must be confirmed inside Awin.", "contact_access": "Join route is the Awin merchant profile; applications are manually reviewed by the brand''s affiliate team per directory reporting.", "credibility": "Operating since 2009 and the best-known specialist retailer in home beauty technology, with programs on five networks.", "niche_fit": "Beauty devices are a fast-growing, highly demonstrable UGC category, though the retailer range extends beyond skincare into wellness tech.", "opportunity_availability": "Open Awin program across multiple regional storefronts with manual application review.", "ugc_evidence": "An established multi-network program exists with creator-facing assets and codes, but the brand publishes no dedicated creator program page in the sources checked."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('PÜR Minerals', 'https://www.purcosmetics.com', 'US clean-beauty brand with more than 20 years in multitasking mineral makeup and skincare, known for the 4-in-1 Pressed Mineral Makeup; its own affiliate page sends creators to sign up through Impact.', 'United States', 'published') returning id into bid;
