  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'PÜR Minerals Affiliate Program (Impact)', 'https://www.purcosmetics.com/pages/affiliates', null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.purcosmetics.com/pages/affiliates', 'brand_site', 'affiliate_program', 'The brand''s own affiliates page (fetched) invites bloggers and beauty influencers to join the PUR Affiliate Program, states affiliates receive a set commission on every sale through their unique link with tracking tools, exclusive promos and coupons, and states ''With Impact, you''ll have access to real-time reporting, creative assets, and unique tools'' with sign-up ''through Impact''. The page does not publish the commission rate, so commission_rate is recorded as null.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.purcosmetics.com/pages/affiliates', 'brand_site', 'commission_cap', 'No earnings-cap or ''unlimited earnings'' statement appears on the fetched brand page, so the cap is recorded as unknown. No creator count is published, so saturation is also unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 13, 7, 9, 9, 4, '{"compensation": "A commission is confirmed by the brand but the rate is unpublished, so compensation scores low until the rate is confirmed inside Impact.", "contact_access": "The brand publishes its own affiliates page naming the network and sign-up route; no public partnerships email was found.", "credibility": "Clean-beauty pioneer of over 20 years with national retail distribution; program existence is verified on the brand''s own page.", "niche_fit": "Mineral complexion products and multitasking makeup are a proven UGC category for base routines and wear tests.", "opportunity_availability": "Open sign-up through Impact linked from the brand''s own page.", "ugc_evidence": "The brand directly recruits bloggers and beauty influencers on its own page with promos and creative support, though rates and creator terms sit inside the network."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Drunk Elephant', 'https://www.drunkelephant.com', 'US clean-skincare brand built on biocompatible ingredients and the ''Suspicious 6'' elimination philosophy, owned by Shiseido; it runs network affiliate programs and a UK creator community, Skin Squad, with commission-based earnings.', 'United States', 'published') returning id into bid;
