  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Drunk Elephant Affiliate Program (Impact, reported) + Skin Squad', 'https://www.drunkelephant.co.uk/gb/en/drunk-elephant-skin-squad/', null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.drunkelephant.co.uk/gb/en/drunk-elephant-skin-squad/', 'brand_site', 'affiliate_program', 'The brand''s own Skin Squad page (fetched) describes a community for content creators and community engagers offering commission affiliate opportunities, personal discount links, free product vouchers and products for content creation, open to UK-based creators aged 18+ with 2,500+ followers on Instagram or TikTok, with tiered rewards as members progress.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://afftank.com/blog/skincare-affiliate-programs', 'affiliate_directory', 'commission_rate', 'Published US rates conflict: AffTank''s skincare program guide reports 8% with a 30-day cookie managed through Impact, LinkApprove''s comparison lists 10% per sale, and a Rakuten Advertising network listing for Canada shows a 3% base commission. With no single rate published on a brand or network page, commission_rate is recorded as null and the conflict documented here. No earnings-cap statement was found, so the cap is unknown; no creator count is published, so saturation is also unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 16, 6, 8, 7, 5, '{"compensation": "No reliable rate could be verified - published figures conflict between 3%, 8% and 10% across networks and directories.", "contact_access": "Creator route is the brand''s own Skin Squad page for the UK and network listings elsewhere; no public partnerships email was found.", "credibility": "Global clean-skincare leader owned by Shiseido with mass Sephora distribution; program evidence is strong for existence, weak for terms.", "niche_fit": "Iconic, colorful, ingredient-led skincare is a top UGC category for routines and ''smoothie'' mixing content.", "opportunity_availability": "Network programs are open, but the brand''s own creator community is application-based, UK-only and requires 2,500+ followers.", "ugc_evidence": "A dedicated creator community with commission earnings, vouchers and featuring opportunities is direct creator evidence, alongside gifted-plus-affiliate PR collaborations reported by creator platforms."}'::jsonb);
