  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.cuelinks.com/blog/top-beauty-skincare-affiliate-programs-india/', 'affiliate_directory', 'commission_rate', 'Published rates conflict: EarnKaro lists a flat 15%, CueLinks'' India beauty program guide lists 12.60% with a 1-day cookie, and Shopper lists 8.96%. With three different figures across platforms and no rate published on a brand page, commission_rate is recorded as null and the conflict documented here. No earnings-cap statement was found, so the cap is unknown; no creator count is published, so saturation is also unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 12, 6, 8, 9, 4, '{"compensation": "Headline rates of 12.6-15% would be strong, but three platforms publish three different figures and none is confirmed on a brand page, so no rate could be recorded.", "contact_access": "Join routes are published on the affiliate platforms; no public partnerships email was found.", "credibility": "One of India''s best-known D2C skincare brands, founded 2018, with wide marketplace and retail presence; program terms rest on platform listings.", "niche_fit": "Affordable, colorful, ingredient-led skincare aimed at younger users is a strong UGC fit for routine and review content.", "opportunity_availability": "Open joining through multiple Indian affiliate platforms with no stated approval requirements.", "ugc_evidence": "Platforms actively market the program to creators, but the brand publishes no own creator program page in the sources checked."}'::jsonb);
