  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.shopper.com/partnerships/embryolisse-com-affiliate-program', 'affiliate_directory', 'commission_rate', 'Shopper''s partnership listing reports a 5-10% payout range for the Embryolisse affiliate program, while Lasso lists the program with the rate unpublished. Because only a range is reported and no flat rate is published on a brand or network page, commission_rate is recorded as null with the range documented here. No earnings-cap statement was found, so the cap is unknown; no creator count is published, so saturation is also unknown.', 'publicly_reported', now());
