  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'YOU Skincare YOU Insiders Program (Shopify Collabs)', 'https://www.youskincare.in/pages/collab', null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.youskincare.in/pages/collab', 'brand_site', 'affiliate_program', 'The brand''s own Collabs page (fetched) describes the YOU Insiders program: a 10% starting commission on eligible sales through a personal referral link, free to apply with applications reviewed, no minimum follower count, commission calculated on eligible product revenue after discounts excluding GST, shipping and refunds, plus a separate Ambassador track with selected campaign and gifting opportunities. Applications run through Shopify Collabs (the page''s apply buttons link to api.collabs.shopify.com). The page also publishes the support email support@youskincare.in and the brand''s Chandigarh address.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.youskincare.in/pages/collab', 'brand_site', 'commission_cap', 'No earnings-cap or ''unlimited earnings'' statement appears on the fetched program page, so the cap is recorded as unknown. No creator count is published, so saturation is also unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 15, 12, 12, 9, 3, '{"compensation": "A published 10% starting rate on the brand''s own page is a fair base for a small brand, though payout timing follows an unpublished programme policy.", "contact_access": "A support email, phone number and postal address are all published on the brand''s own program page.", "credibility": "Full program FAQs are published on the brand''s own page, but the brand is young and small with limited independent coverage.", "niche_fit": "Capsule creams with texture-led content ideas fit routine UGC, though the range is narrow and India-only.", "opportunity_availability": "Open application with no minimum follower count, reviewed by the brand.", "ugc_evidence": "A dedicated creator program with a creative library, campaign briefs, dashboard guidance and content ideas per product is strong creator evidence."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Concept2', 'https://www.concept2.com/', 'The dominant indoor-rowing brand - RowErg, SkiErg and BikeErg ergs plus racing oars, sold direct online since 1976. Its US affiliate program runs on Awin and pays a published 5% commission on referrals to its online shop; the machines are big-ticket staples of home-gym, CrossFit and Hyrox training content. No earnings-cap statement is published, so the cap stays unknown, and no creator counts are published, so saturation stays unknown.', 'United States', 'published') returning id into bid;
