  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 13, 11, 9, 8, 5, '{"niche_fit": "The RowErg is the default rowing machine in home-gym tours, Hyrox prep and CrossFit content - erg scores and split times are inherently filmable, comparable content.", "ugc_evidence": "Open Awin program for a brand whose machines anchor a huge volume of training content; no dedicated creator page was verified beyond the network profile.", "compensation": "5% on machines that sell for around $1,000 means roughly $50 per sale; rate verified on the network profile itself.", "contact_access": "Join route is via the Awin profile; no public affiliate email was verified.", "opportunity_availability": "Open Awin program; standard network approval applies.", "credibility": "Category-defining brand founded in 1976; rate verified on Awin itself."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Funwater', 'https://www.funwaterboard.com/', 'Inflatable stand-up paddle board brand (Funwater Outdoor) selling premium SUPs in 30+ countries, with a US & Canada affiliate program on Awin paying a published 10% commission - positioned by the brand as one of the highest in its industry - and a named partnerships contact on the profile. No earnings-cap statement is published, so the cap stays unknown, and no creator counts are published, so saturation stays unknown.', null, 'published') returning id into bid;
