  insert into public.brands (name, website, description, country, status) values ('Kettlebell Kings', 'https://www.kettlebellkings.com/', 'Specialist kettlebell brand selling competition and cast-iron bells, weighted vests, battle ropes and training accessories. Its affiliate program runs on AvantLink at a published 5% sales commission with monthly payouts and a dedicated support team, but only a 1-day referral window, which the score reflects. No earnings-cap statement is published, so the cap stays unknown, and no creator counts are published, so saturation stays unknown.', null, 'published') returning id into bid;
