  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 12, 10, 9, 8, 4, '{"niche_fit": "Kettlebell flows, swing tutorials and home-gym setups are a durable fitness-content niche, and this is a specialist brand in it.", "ugc_evidence": "Open AvantLink program with a dedicated support team; no creator-specific page was verified.", "compensation": "5% is mid-range and the 1-day cookie is the shortest in this batch, which caps the compensation score.", "contact_access": "Join route is via AvantLink through the directory profile; no public affiliate email was verified.", "opportunity_availability": "Open AvantLink program; standard network approval applies.", "credibility": "Established specialist brand; terms rest on one detailed directory source."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Franklin Sports', 'https://franklinsports.com/', 'Family sporting-goods brand founded in 1946 - baseball, soccer, football and basketball gear, backyard games and fitness accessories, with official league partnerships. Its affiliate program runs on Impact at a published 3% per sale, open to all regions. The rate is low, which the score reflects. No earnings-cap statement is published, so the cap stays unknown, and no creator counts are published, so saturation stays unknown.', null, 'published') returning id into bid;
