  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkclicky.com/affiliate-program/franklin-sports/', 'affiliate_directory', 'commission_rate', 'The LinkClicky directory profile for Franklin Sports lists the program on the Impact platform, open to all regions, paying 3% per sale, and its FAQ repeats: ''The commission rate for Franklin Sports is 3% per sale. This is just what''s officially listed with their affiliate program as the payout.'' The 3% rate is recorded. No earnings-cap statement appears, so the cap is recorded as unknown.', 'publicly_reported', now());
