  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 20, 11, 7, 9, 8, 5, '{"niche_fit": "Backyard games, pickleball and youth-sports gear are steady family-fitness content, though less creator-led than gym equipment.", "ugc_evidence": "Open Impact program documented for publishers and influencers; no creator-specific page was verified.", "compensation": "3% is a low rate even on mid-priced gear; directory-reported as the officially listed payout.", "contact_access": "Join route is via Impact through the directory profile; no public partnerships email was verified.", "opportunity_availability": "Open Impact program, all regions; standard network approval applies.", "credibility": "Sporting-goods brand operating since 1946 with major league partnerships; terms rest on one directory source."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Sunny Health & Fitness', 'https://sunnyhealthfitness.com/', 'Budget home-fitness equipment brand - indoor cycles, treadmills, rowers, ellipticals and steppers. Its own affiliate page describes tiered commissions reaching a 10% tier on named best-sellers with a 30-day cookie and publishes an affiliate contact email, but it never states a base rate, and an Impact performance listing shows 3% - so the rate is recorded as null rather than guessed from conflicting figures. No earnings-cap statement is published, so the cap stays unknown.', null, 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'fitness'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'partnerships', 'affiliate@sunnyhealthfitness.com', null, 'https://sunnyhealthfitness.com/blogs/health-wellness/make-money-sunny-health-fitness-affiliate-program', 'verified', now());
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Impact', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://sunnyhealthfitness.com/blogs/health-wellness/make-money-sunny-health-fitness-affiliate-program.', 'https://sunnyhealthfitness.com/blogs/health-wellness/make-money-sunny-health-fitness-affiliate-program', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Sunny Health & Fitness Affiliate Program (Impact)', 'https://sunnyhealthfitness.com/blogs/health-wellness/make-money-sunny-health-fitness-affiliate-program', 'https://sunnyhealthfitness.com/blogs/health-wellness/make-money-sunny-health-fitness-affiliate-program', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://sunnyhealthfitness.com/blogs/health-wellness/make-money-sunny-health-fitness-affiliate-program', 'official_program_page', 'commission_rate', 'Sunny''s own affiliate page states the program ''offers different tiers of commission for different exercise equipment products. You''ll earn up to 10% commission'' and names specific bikes (SF-B1986, SF-B1851, SF-B1879) in the 10% tier, with a 30-day attribution window. ''Up to 10%'' is a tier ceiling, not a base rate, so no base rate is taken from this page.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://compareepc.com/health-affiliate-programs/', 'affiliate_directory', 'commission_rate', 'CompareEPC''s payout-data listing for Sunny Health & Fitness on Impact shows a 3% commission - which conflicts with the brand page''s 10% top tier and cannot be reconciled into a single base rate. commission_rate is therefore recorded as null with the conflict documented here. No earnings-cap statement appears in either source, so the cap stays unknown.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://sunnyhealthfitness.com/blogs/health-wellness/make-money-sunny-health-fitness-affiliate-program', 'official_program_page', 'creator_program', 'The same brand page runs an open application (approval in 24-48 hours), explicitly welcomes influencers and bloggers, and publishes the contact affiliate@sunnyhealthfitness.com for program inquiries - the contact recorded. No creator counts are published, so creator_saturation stays unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 13, 8, 11, 8, 4, '{"niche_fit": "Affordable home cardio gear is a volume category for review and setup content - bikes, rowers and treadmills at accessible prices.", "ugc_evidence": "The brand''s own page is written directly for influencers and affiliates with an open application route.", "compensation": "Rate is null: the brand publishes only a 10% top tier while an Impact listing shows 3%, so compensation scores low until confirmed inside the program.", "contact_access": "A public affiliate email (affiliate@sunnyhealthfitness.com) is published on the brand''s own page.", "opportunity_availability": "Open application on the brand page with stated 24-48 hour approval.", "credibility": "Large, long-running budget equipment brand; the rate conflict is documented honestly rather than resolved by guessing."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('KETL', 'https://ketlmtn.com/', 'Technical outdoor apparel brand (KETL Mountain) making travel, hiking, mountain-bike and trail clothing with a lifetime repair program. Its own affiliate page is built explicitly for established creators, reviewers and media sites, runs through its GoAffPro portal, and advertises ''up to 20% commission'' with a 45-day cookie and a $135 average order - an ''up to'' figure is a ceiling, so the base rate is recorded as null. Applications are individually reviewed. No earnings-cap statement is published, so the cap stays unknown.', null, 'published') returning id into bid;
