  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'KETL Affiliate Program (Brand direct)', 'https://ketlmtn.com/pages/affiliates', 'https://ketlmtn.com/pages/affiliates', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ketlmtn.com/pages/affiliates', 'official_program_page', 'commission_rate', 'KETL''s own affiliate page lists ''Up to 20% commission rate'', a 45-day cookie, free US shipping and a $135 average order value. An ''up to'' figure is a rate ceiling, not a base rate, so commission_rate is recorded as null rather than guessed. No earnings-cap statement appears, so the cap is recorded as unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ketlmtn.com/pages/affiliates', 'official_program_page', 'creator_program', 'The same page states the program ''is built for established creators, media sites, YouTube channels, gear reviewers, and social accounts with a real audience'', that every application is reviewed, and routes signup to its GoAffPro portal (ketlmtn.goaffpro.com). No creator counts are published, so creator_saturation stays unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 15, 8, 9, 7, 4, '{"niche_fit": "Technical travel-and-trail apparel sits right in the outdoor-creator wardrobe niche - packable, demonstrable, review-friendly.", "ugc_evidence": "The brand''s own page is explicitly creator-first, naming YouTube channels, reviewers and social accounts as its target partners.", "compensation": "Only an ''up to 20%'' ceiling is published, so the rate is null and compensation scores low until confirmed after application.", "contact_access": "Apply on the brand''s own page into its portal; no public affiliate email was verified.", "opportunity_availability": "Open application but individually reviewed and selective by the brand''s own description.", "credibility": "Established DTC outdoor apparel brand with a lifetime repair program; ceiling-only rate keeps credibility mid-range."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Darn Tough', 'https://www.darntough.com/', 'Vermont merino-wool sock brand famous for its unconditional lifetime guarantee, spanning hiking, running, ski and everyday lines. The brand''s own influencer FAQ confirms a running affiliate program (separate from its points-based friend referral scheme, which is not the route recorded here); the program sits on Impact per its affiliate agency''s announcement, and directories publish only a 1.6%-8% range, so the base rate is recorded as null. No earnings-cap statement is published, so the cap stays unknown.', null, 'published') returning id into bid;
