  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Impact', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://darntough.com/pages/faqs-influencers-pros.', 'https://darntough.com/pages/faqs-influencers-pros', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Darn Tough Affiliate Program (Impact)', 'https://darntough.com/pages/faqs-influencers-pros', 'https://darntough.com/pages/faqs-influencers-pros', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://darntough.com/pages/faqs-influencers-pros', 'official_program_page', 'creator_program', 'Darn Tough''s own ''FAQ: Influencers & Pros'' page answers ''How can I become a Darn Tough affiliate partner?'' by linking to its affiliate program - confirming the program exists on the brand''s own site, distinct from the Micro Crew Rewards friend-referral scheme described separately on the same page.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/darn-tough-vermont/', 'affiliate_directory', 'commission_rate', 'The Lasso directory profile for Darn Tough Vermont lists a commission of ''1.6% to 8% Per Sale'' with a 60-day cookie - a range, not a base rate, so commission_rate is recorded as null. The brand''s affiliate agency (Clique Affiliate Marketing) has separately announced the program as joinable on impact.com, which is the network recorded. No earnings-cap statement appears, so the cap stays unknown, and no creator counts are published, so saturation stays unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 21, 12, 7, 9, 8, 5, '{"niche_fit": "Guaranteed-for-life merino socks are a beloved thru-hiking, running and ski-wardrobe staple with a strong story for gear content.", "ugc_evidence": "Program existence is confirmed on the brand''s own influencer FAQ; no creator-specific program page was verified beyond it.", "compensation": "Only a 1.6%-8% range is published, so the rate is null and compensation scores low until confirmed inside Impact.", "contact_access": "Join route is via Impact, linked from the brand''s own FAQ; no public partnerships email was verified.", "opportunity_availability": "Open Impact program; standard network approval applies.", "credibility": "Iconic US-made sock brand with a lifetime guarantee; the range-only rate is documented honestly."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('OARS', 'https://www.oars.com/', 'Guided rafting and adventure-travel outfitter running professionally led river trips across the American West since 1969. Its own affiliate page publishes the full rate card - 4% on multi-day domestic river trips (average booking $3,000) and 6% on 1-day and 2-day American River trips (average booking $1,000) - through Awin with a 60-day cookie; the 4% flagship multi-day rate is recorded. The page explicitly recruits influencers and content creators. No earnings-cap statement is published, so the cap stays unknown.', null, 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'travel'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Awin', 4, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://www.oars.com/affiliate-program/.', 'https://www.oars.com/affiliate-program/', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'OARS Affiliate Program (Awin)', 'https://www.oars.com/affiliate-program/', 'https://www.oars.com/affiliate-program/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.oars.com/affiliate-program/', 'official_program_page', 'commission_rate', 'OARS'' own affiliate page states: ''4% commission on multi-day domestic river trips in the U.S., excluding Alaska and Grand Canyon (Average booking value: $3,000)'' and ''6% commission on 1-day trips and 2-day American River trips (Average booking value: $1,000)'', tracked through Awin with a 60-day cookie. The 4% multi-day rate is recorded as the headline rate with the 6% tier documented here. No earnings-cap statement appears, so the cap is recorded as unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.oars.com/affiliate-program/', 'official_program_page', 'creator_program', 'The same page says ''We work with high-caliber publishers, writers, influencers, and content creators'' in outdoor and adventure travel, and routes signup through Awin. No creator counts are published, so creator_saturation stays unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 14, 13, 9, 8, 5, '{"niche_fit": "Guided river trips are premium adventure-travel content - Grand Canyon and Salmon River itineraries are bucket-list material creators film extensively.", "ugc_evidence": "The brand''s own page explicitly recruits influencers and content creators, not just publishers.", "compensation": "4% of a $3,000 average multi-day booking is about $120 per sale (6% on shorter trips); full rate card verified on the brand''s own page.", "contact_access": "Apply via the brand page into Awin; a named program contact is referenced on the page but no readable email address was verified, so none is recorded.", "opportunity_availability": "Open Awin program; standard network approval applies.", "credibility": "Outfitter operating since 1969; complete published terms on its own page."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('battleface', 'https://www.battleface.com/', 'Digital-first travel insurance specialist built for adventure travellers - customisable trip, medical and gear cover sold in 60+ countries. Its affiliate program runs direct through Refersion at a published 15% per sale with a 30-day cookie and monthly payouts, one of the highest flat percentage rates among travel-insurance programs. No earnings-cap statement is published, so the cap stays unknown, and no creator counts are published, so saturation stays unknown.', null, 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'travel'), true);
