  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://atlas.hellosafe.com/travel-insurance-affiliate-program/best-programs/', 'affiliate_directory', 'commission_rate', 'The HelloSafe Atlas comparison of travel-insurance affiliate programs lists battleface at ''15% per sale'', a 30-day cookie, network ''Direct (Refersion)'' and monthly payouts, describing it as ''one of the highest flat-percentage rates in this comparison'' with reach across 60+ countries. The 15% rate is recorded. No earnings-cap statement appears, so the cap is recorded as unknown.', 'publicly_reported', now());
