  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 11, 15, 9, 8, 4, '{"niche_fit": "Adventure-travel insurance is a natural sponsor fit for trekking, diving and expedition content where standard policies fall short.", "ugc_evidence": "Open program documented in a structured program comparison; no dedicated creator page was verified.", "compensation": "15% of premium is at the top of the travel-insurance range; directory-reported from a scored comparison of 20 programs.", "contact_access": "Join route is via the Refersion program through the directory profile; no public partnerships email was verified.", "opportunity_availability": "Open direct program via Refersion; standard approval applies.", "credibility": "Established specialist insurer in 60+ countries; terms rest on one comparison source rather than the brand''s own page."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Faye', 'https://www.withfaye.com/', 'Modern, digital-first US travel protection brand - whole-trip cover with proactive care and fast claims, rated 4.8/5 on Trustpilot per its own site. Its partner page runs explicit tracks for content creators and affiliate partners, with the affiliate program on Impact; published flat-fee figures conflict ($4 per sale in one payout tracker, $30 in a network listing), so the rate is recorded as null with the conflict documented. No earnings-cap statement is published, so the cap stays unknown.', 'United States', 'published') returning id into bid;
