  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.withfaye.com/partners/', 'official_program_page', 'creator_program', 'Faye''s own partner page lists dedicated tracks for ''Content creators'' (''Recommend a travel product your audience will actually thank you for. Earn while building trust'') and ''Affiliate partners'' (''Turn travel intent into meaningful revenue... Apply here'') - confirming a creator-facing affiliate route on the brand''s own site. No creator counts are published, so creator_saturation stays unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://compareepc.com/travel-insurance-affiliate-programs/', 'affiliate_directory', 'commission_rate', 'CompareEPC''s payout-data table lists Faye Travel Insurance on Impact at a flat $4 per sale, while a SaleGains network listing for the same program shows a flat $30 per purchase with a 30-day cookie. The two published flat figures conflict and neither is a percentage base rate, so commission_rate is recorded as null with the conflict documented here. No earnings-cap statement appears, so the cap is recorded as unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 13, 7, 9, 8, 5, '{"niche_fit": "Trip protection is a standard packing-list and booking-flow topic for travel creators, and Faye''s app-first product demos well on camera.", "ugc_evidence": "The brand''s own partner page has an explicit content-creator track alongside its affiliate track.", "compensation": "Rate is null: published flat fees conflict ($4 vs $30 per sale), so compensation scores low until confirmed inside Impact.", "contact_access": "Apply via the brand''s partner page into Impact; no public partnerships email was verified.", "opportunity_availability": "Open Impact program; standard network approval applies.", "credibility": "Highest-rated US travel protection brand per its own published Trustpilot/BBB figures; the rate conflict is documented honestly."}'::jsonb);
