  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 15, 8, 6, 8, 5, '{"niche_fit": "Clean medicine for kids and families is a strong fit for parenting and family-health creators.", "ugc_evidence": "The brand actively recruits everyday recommenders on its own Instagram, framing the program around people already sharing the products.", "compensation": "No settled rate could be verified - directory figures conflict (up to 26.25% vs 5-10%) - so the rate is null and compensation scores low until the program publishes terms.", "contact_access": "No public affiliate email is published; joining runs through Levanta via the brand''s bio link.", "opportunity_availability": "Free and open to join per the brand''s own announcement.", "credibility": "Certified B Corp status and clean-label positioning are published by the brand and its directory listings."}'::jsonb);
