  insert into public.brands (name, website, description, country, status) values ('Firepaw', 'https://firepaw.eu', 'Bulgarian maker of handcrafted dog treadmills (slatmills and carpet mills) and K9 training equipment, built in its own workshop in Parvenets, Bulgaria. Its Ambassador-Affiliate Program pays a flat 6% commission on every sale made through a unique code or link — on treadmills averaging €1,600–€2,200 and on every other product in the basket — and the program page states there are no caps and no limits on earnings.', 'Bulgaria', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'pets'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'general', 'info@firepaw.eu', 'https://firepaw.eu/contact/', 'https://firepaw.eu/contact/', 'verified', now());
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Brand direct', 6, 'Commission cap: UNCAPPED — stated in the program terms (see evidence). Creator saturation: unknown (see evidence). Rate as reported by https://firepaw.eu/join-the-firepaw-ambassador-affiliate-program/.', 'https://firepaw.eu/join-the-firepaw-ambassador-affiliate-program/', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Firepaw Ambassador-Affiliate Program — brand''s own page publishes 6% commission with ''no caps, no limits'' on earnings', 'https://firepaw.eu/join-the-firepaw-ambassador-affiliate-program/', 'https://firepaw.eu/join-the-firepaw-ambassador-affiliate-program/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://firepaw.eu/join-the-firepaw-ambassador-affiliate-program/', 'official_site', 'affiliate', 'Firepaw''s own Ambassador-Affiliate Program page fetched in full: ''Earn 6% commission on every sale generated through your unique code or link'', average treadmill price €1,600–€2,200, commission also paid on every other product added to the basket, repeat purchases tracked, and ''Competitive Commission: Earn a fair 6% from every sale—no caps, no limits.'' The explicit no-caps/no-limits earnings statement is on the brand''s own site, so commission_cap is recorded as uncapped. Sign-up is by getting in touch and the team sets up the affiliate account. The program is tailored for dog trainers, influencers, veterinarians and dog enthusiasts. No creator count is published, so saturation stays unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://firepaw.eu/contact/', 'official_site', 'affiliate', 'Firepaw''s own contact page fetched in full: company SIMINVEST EOOD, Parvenets 4110, Bulgaria; published email info@firepaw.eu; phone +359 876 600 800. The page also states the treadmills are ''entirely handcrafted & designed in our own workshop''.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 14, 12, 12, 8, 4, '{"compensation": "6% is modest as a percentage but applies to \u20ac1,600\u2013\u20ac2,200 treadmills (roughly \u20ac96\u2013\u20ac132 per treadmill sale) and the brand states earnings are uncapped", "contact_access": "Published general email (info@firepaw.eu) and phone on the brand''s own contact page; sign-up is a direct conversation with the team", "credibility": "Established specialist maker crafting treadmills in-house in Bulgaria, with professional K9 and military working-dog clientele cited on its own pages", "niche_fit": "Dog treadmills and K9 fitness gear are a focused but fast-growing pet-fitness niche; high-ticket hardware makes strong demo and training content", "opportunity_availability": "Open to trainers, influencers, vets and enthusiasts; accounts are set up manually after contact rather than instant self-serve approval", "ugc_evidence": "A brand-run ambassador-affiliate program explicitly recruiting influencers and trainers, with an exclusive gift perk for the ambassador''s audience"}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Infinity Flow 3D', 'https://infinityflow3d.com', 'US 3D-printing automation company founded out of a Purdue University senior project, selling the S1 Plus automatic filament reloader and the FlowQ print-farm software subscription. It runs two affiliate programs — one for physical products and one for FlowQ software subscriptions — and both program pages state in their FAQs that there is no cap on how much an affiliate can earn; no commission percentage is published on either page, so the rate is recorded as null.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'technology'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'creator_application', null, 'https://infinityflow3d.bixgrow.com', 'https://infinityflow3d.com/pages/infinity-flow-3d-printing-affiliate-program', 'verified', now());
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'general', 'contact@infinityflow3d.com', 'https://infinityflow3d.com/collections/all-products/products/s1-plus-automatic-filament-loader', 'https://infinityflow3d.com/collections/all-products/products/s1-plus-automatic-filament-loader', 'verified', now());
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'BixGrow', null, 'Commission cap: UNCAPPED — stated in the program terms (see evidence). Creator saturation: unknown (see evidence). Rate as reported by https://infinityflow3d.com/pages/infinity-flow-3d-printing-affiliate-program.', 'https://infinityflow3d.bixgrow.com', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Infinity Flow Affiliate Programs — brand''s own pages state ''no cap on how much you can earn'' for both hardware and FlowQ software referrals', 'https://infinityflow3d.bixgrow.com', 'https://infinityflow3d.com/pages/infinity-flow-3d-printing-affiliate-program', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://infinityflow3d.com/pages/infinity-flow-3d-printing-affiliate-program', 'official_site', 'affiliate', 'Infinity Flow''s own product affiliate program page fetched in full. FAQ: ''How much can I earn? You earn commission on every sale made through your custom link or coupon. There''s no cap on how much you can earn.'' Affiliates must run an active content platform (YouTube, TikTok, Instagram or blog) in the 3D printing, maker or tech space; select affiliates receive free products and others up to 50% off; a media kit is provided; sales are tracked via unique link and coupon code; application runs through the brand''s BixGrow portal (infinityflow3d.bixgrow.com). No commission percentage is published on the page, so commission_rate is null. The explicit no-cap statement is on the brand''s own page, so commission_cap is uncapped.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://infinityflow3d.com/pages/flowq-3d-printing-software-affiliate-program', 'official_site', 'affiliate', 'The brand''s FlowQ software affiliate program page fetched in full repeats the same FAQ: ''There''s no cap on how much you can earn.'' FlowQ affiliates earn recurring commission on every payment a referred customer makes for up to 36 months, including upgrades and plan changes, tracked with a 60-day cookie and last-click attribution. The brand encourages joining both the hardware and software programs. No percentage is published here either. The brand''s own site also publishes contact@infinityflow3d.com on its product pages, and its refund policy names the company as Infinity Flow 3D Printing LLC; Purdue University''s engineering site documents the company as founded by Purdue alumni from a senior design project, and FlowQ is described on the brand''s site as developed and hosted in the United States.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 16, 8, 10, 8, 3, '{"compensation": "Earnings are explicitly uncapped and the software program pays recurring commission for up to 36 months, but no percentage is published on either fetched page, so the rate cannot be scored higher", "contact_access": "Self-serve application through the brand''s BixGrow portal plus a published general email (contact@infinityflow3d.com)", "credibility": "A very young company (founded 2024 out of a Purdue senior project, Kickstarter-launched) \u2014 real and documented, but with a short track record", "niche_fit": "3D printer automation is squarely in the maker/tech creator niche \u2014 printer farms, filament management and print-fail content are natural UGC", "opportunity_availability": "Open application for creators in the 3D printing/maker space; the brand expects affiliates to stay active and may pause inactive accounts", "ugc_evidence": "Both program pages are written for creators: an active YouTube/TikTok/Instagram/blog audience is required, a media kit is supplied, and select affiliates get free product"}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Elegoo', 'https://www.elegoo.com', 'Shenzhen-based consumer 3D printing and STEM electronics brand behind the Mars and Saturn resin printers, the Neptune FDM series and Arduino-style learning kits. Its own global affiliate page publishes a 5%+ commission rate and a $300 average customer order, with joining handled through ShareASale or Impact and a published affiliate contact email (affiliate@elegoo.com).', 'China', 'published') returning id into bid;
