  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Impact', 5, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://global.elegoo.com/pages/elegoo-affiliate-impact-awin.', 'https://global.elegoo.com/pages/elegoo-affiliate-impact-awin', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Elegoo Affiliate Program — brand''s own page publishes 5%+ commission and $300 average order via ShareASale or Impact', 'https://global.elegoo.com/pages/elegoo-affiliate-impact-awin', 'https://global.elegoo.com/pages/elegoo-affiliate-impact-awin', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://global.elegoo.com/pages/elegoo-affiliate-impact-awin', 'official_site', 'affiliate', 'Elegoo''s own global affiliate page fetched in full: ''5%+ Commission rate'', ''$300 Average customer order'', ''8+ Years Expertise in industry''. Joining: ''Click the Join Us button below to create a free ShareAsale or Impact account'', apply, receive an approval email, get unique links, commissions paid monthly. The page explicitly welcomes YouTubers, bloggers, journalists, forum/community managers and influencers on Facebook and Instagram, and publishes the contact ''feel free to email us at affiliate@elegoo.com''. The page''s Join Us button routes to Impact (app.impact.com). No earnings-cap statement is published, so the cap is unknown; no creator count is published, so saturation is unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkclicky.com/affiliate-program/elegoo/', 'directory', 'affiliate', 'LinkClicky''s program listing records Elegoo at 5% per sale on the Impact platform, consistent with the 5%+ floor the brand publishes on its own page; directory roundups also describe performance incentives above the base rate on the network programs. The brand is headquartered in Shenzhen, China, per multiple published company profiles.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 16, 10, 13, 9, 5, '{"compensation": "A brand-published 5% floor on a $300 average order is about $15 per sale, with performance incentives reported above base; no cap statement is published", "contact_access": "Published affiliate email (affiliate@elegoo.com) on the brand''s own program page plus direct network join buttons", "credibility": "One of the largest consumer 3D printing brands globally, operating 8+ years with worldwide retail distribution", "niche_fit": "Consumer resin and FDM 3D printers plus STEM kits are core maker/tech UGC \u2014 print tests, resin miniature painting and build projects", "opportunity_availability": "Open application through ShareASale or Impact with approval by email; free to join", "ugc_evidence": "The brand''s own page recruits YouTubers, bloggers and social influencers by name, and the program runs on two major creator-friendly networks"}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('XPPen', 'https://www.xp-pen.com', 'Pen display and drawing tablet brand (Artist and Deco series) founded in 2005 and headquartered in China. Its own affiliate programs page publishes commission rates of 5%–20% on an average order amount of $250+, a 30-day cookie, and four ways to join — ShareASale, Impact, Admitad and an in-house program — with higher tiers for excellent affiliates. The recorded rate is the published 5% entry floor of that brand-published range.', 'China', 'published') returning id into bid;
