  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'XPPen Affiliate Programs — brand''s own page publishes 5%–20% commission tiers on $250+ average orders across ShareASale, Impact, Admitad and in-house', 'https://www.xp-pen.com/affiliate/programs', 'https://www.xp-pen.com/affiliate/programs', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.xp-pen.com/affiliate/programs', 'official_site', 'affiliate', 'XPPen''s own affiliate programs page fetched: ''5% - 20% Commission Rates, Monthly Paid'', ''$250+ Average Order Amount'', ''30 Day Cookie''. FAQ: ''We pay a 5%-20% commission to you on AOV $250+. Excellent affiliates are eligible for higher commission levels.'' Joining is free on ShareASale, Impact, Admitad and the XPPen in-house affiliate program; the page lists merchant IDs for the network programs. The recorded commission_rate is 5, the floor of the brand''s own published range — the range itself is documented here rather than guessed. No earnings-cap statement is published (the 20% is a rate ceiling, not an earnings cap), so the cap is unknown; no creator count is published, so saturation is unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 15, 12, 9, 9, 4, '{"compensation": "Brand-published 5%\u201320% range on $250+ average orders; the recorded 5% is the entry floor and top tiers are genuinely high for hardware", "contact_access": "Application routes from the brand''s own program page into the networks; no affiliate email address was published in the fetched page text", "credibility": "A top-three global pen-tablet brand founded in 2005 with worldwide distribution", "niche_fit": "Drawing tablets are a staple of digital-art and tech creator content \u2014 reviews, speedpaints, desk setups and artist workflow videos", "opportunity_availability": "Four open join routes, free to sign up, monthly payment", "ugc_evidence": "A dedicated brand affiliate hub recruiting creators across three networks plus an in-house program, with tier progression for strong performers"}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('BrüMate', 'https://www.brumate.com', 'US insulated drinkware brand known for can coolers and tumblers engineered to fit slim and standard cans (Hopsulator line) and leak-proof travel mugs. Its affiliate program is managed through ShareASale and pays a flat 10% per sale on a 30-day cookie, with higher rates available to top performers, and it actively recruits bloggers, TikTok and Instagram creators and review sites.', 'United States', 'published') returning id into bid;
