  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/brumate/', 'directory', 'affiliate', 'Lasso''s BrüMate program page records a 10% per-sale commission and a 30-day cookie for the BrüMate affiliate program. No earnings-cap statement is published, so the cap is unknown, and no creator count is published, so saturation is unknown.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://uppromote.com/affiliate-directory/brumate/', 'directory', 'affiliate', 'UpPromote''s program directory entry for BrüMate: commission typically starts at 10% per sale and can go higher for top performers, calculated on net sales excluding shipping and taxes; the program is managed through third-party networks and has historically been very active on ShareASale; accepted traffic sources include blogs, social media (Instagram, TikTok, YouTube), email newsletters and review sites; the program focuses on US traffic. A separate published PR contact, media@brumate.com, is a press inbox — the affiliate program is the brand''s published creator route.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 15, 13, 8, 9, 5, '{"compensation": "A flat 10% per sale is solid for drinkware and published sources say top performers can earn above the base rate; no cap statement is published", "contact_access": "Application runs through ShareASale; the brand publishes a PR email (media@brumate.com) but no direct affiliate inbox was found on a fetched page", "credibility": "A large, established US DTC drinkware brand with national retail presence", "niche_fit": "Insulated drinkware is proven home and lifestyle UGC \u2014 fit tests, temperature tests and tailgate/camping content perform well in short form", "opportunity_availability": "Open network application with typical approval in a few days", "ugc_evidence": "The program explicitly accepts and recruits TikTok, Instagram and YouTube creators and review sites, and the product is highly visual"}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Drinkmate', 'https://drinkmate.us', 'Home carbonation brand based in Ann Arbor, Michigan, whose OmniFizz and Spritzer machines can carbonate any cold beverage — juice, tea, wine and cocktails, not just water — using a patented Fizz Infuser. Its affiliate program runs on Awin, where the brand''s merchant profile publishes an 8% base commission for all publishers on new customers (5% on existing customers), with dedicated 10% tiers for content and influencer publishers.', 'United States', 'published') returning id into bid;
