  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/93963/commission-groups?setLocale=pt_BR', 'directory', 'affiliate', 'Drinkmate''s own Awin merchant profile (merchant 93963) fetched: CPA structure — Base Commission (All Publishers) 8% on new customers and 5% on existing customers; Content / Mass Media publishers 10% / 10%; Influencers 8% / 5%; attribution period (cookie) 45 days. The recorded commission_rate is the 8% all-publisher base on new customers, with the tier structure documented here. No earnings-cap statement is published, so the cap is unknown; no creator count is published, so saturation is unknown.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://idrinkproducts.com/blogs/news/drinkmate-celebrates-a-decade-of-innovation', 'official_site', 'affiliate', 'Drinkmate''s own company press release on idrinkproducts.com: the brand was founded in July 2014, is based in Ann Arbor, Michigan, and serves as the global headquarters for the Drinkmate brand; its carbonators (OmniFizz, LUX, Spritzer) carbonate any cold beverage, and the release directs readers to Drinkmate.us.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 14, 12, 8, 9, 5, '{"compensation": "8% base on new customers with a published 10% content tier and a 45-day cookie is competitive for small kitchen appliances; no cap statement is published", "contact_access": "Application runs through the brand''s Awin merchant profile; no affiliate email was published on the fetched pages", "credibility": "Operating since 2014 with its own Michigan headquarters, global operations and national retail distribution including Best Buy", "niche_fit": "Home carbonation is a kitchen UGC staple \u2014 sparkling cocktails, sodas and drink recipes are natural short-form content, and Drinkmate carbonates drinks rivals cannot", "opportunity_availability": "Live, joinable program on a major network", "ugc_evidence": "The brand''s Awin profile carries dedicated Content / Mass Media and Influencer publisher tiers, showing an active creator channel"}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Blendtec', 'https://www.blendtec.com', 'US premium high-performance blender brand selling through blendtec.com. It runs a creator-focused affiliate program — listed on the brand''s own affiliates page and managed through AvantLink — aimed at kitchen and food creators and bloggers. Published third-party figures for the rate conflict (up to 8%, 5–8%, and an ''up to 23.94%'' directory figure), so no single rate could be verified and commission_rate is recorded as null with the conflict documented.', 'United States', 'published') returning id into bid;
