  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Blendtec Affiliate Program via AvantLink — creator program listed on the brand''s own affiliates page; published rate figures conflict', 'https://www.blendtec.com/pages/affiliates', 'https://www.bravodm.com/brands/blendtec', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.bravodm.com/brands/blendtec', 'directory', 'affiliate', 'BravoDM''s checked program listing (October 2026) describes Blendtec''s creator program: kitchen and food creators and bloggers promote Blendtec high-performance blenders through affiliate links and banners; the program is listed on the brand''s own page, blendtec.com/pages/affiliates, with application on that page, and runs via AvantLink. No rate is stated in this listing.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.shopper.com/partnerships/blendtec-com-affiliate-program', 'directory', 'affiliate', 'Published rate figures for Blendtec''s program conflict across fetched sources: Shopper.com''s partnership listing claims ''up to 23.94% payout per sale'', CouponFollow''s Blendtec page says affiliates earn ''a commission of up to 8% for every sale'', and Creator-Hero''s program comparison puts Blendtec at ''around 5-8%''. Because the sources conflict and no fetched brand page publishes the rate, commission_rate is recorded as null. No earnings-cap statement is published anywhere fetched, so the cap is unknown; no creator count is published, so saturation is unknown.', 'needs_review', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 14, 7, 9, 8, 5, '{"compensation": "Published figures conflict (5\u20138% vs up to 8% vs up to 23.94%) and no brand page settles the rate, so compensation is scored conservatively until verified at application", "contact_access": "Application is hosted on the brand''s own affiliates page, with the program managed on AvantLink", "credibility": "A long-established US premium blender manufacturer with national retail presence", "niche_fit": "Premium blenders are proven kitchen UGC \u2014 smoothie, soup and ''will it blend'' style demonstrations are natural creator content", "opportunity_availability": "Live program joinable through the brand''s page and AvantLink", "ugc_evidence": "A creator program explicitly built for kitchen and food creators and bloggers, with affiliate links and banners"}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Ruffwear', 'https://ruffwear.com', 'Performance outdoor dog gear brand (harnesses, packs, boots, coats and life jackets) built for trail, snow and water adventures with dogs. Its affiliate program runs through AvantLink at a published 8% commission with a 30-day cookie and an average order value around $85, with sign-up routed from the brand''s own affiliate program page.', 'United States', 'published') returning id into bid;
