  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 15, 12, 9, 9, 5, '{"compensation": "A published 8% on an ~$85 average order is mid-range for pet gear; no cap statement is published", "contact_access": "Sign-up is routed from the brand''s own affiliate program page into AvantLink; no affiliate email was published on the fetched pages", "credibility": "The category-defining performance dog gear brand, US-based and established for three decades", "niche_fit": "Outdoor dog gear sits at the center of adventure-pet UGC \u2014 hiking, camping and trail content with dogs is a large, engaged creator niche", "opportunity_availability": "Open application through AvantLink, a curated but joinable network", "ugc_evidence": "The program targets outdoor dog blogs and YouTube channels, and the brand runs an active ambassador community producing trail content"}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Zee.Dog', 'https://www.zeedog.com', 'Brazilian pet lifestyle brand founded in Rio de Janeiro in 2012, known for design-led collars, leashes, harnesses, beds and toys sold globally through zeedog.com. Its affiliate program pays a published 8% per sale with a 30-day cookie; the network hosting the program is not named on the fetched directory pages, so the route is recorded as unknown — verify at application.', 'Brazil', 'published') returning id into bid;
