  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Zee.Dog Affiliate Program — published 8% per sale with a 30-day cookie for the design-led dog accessories brand', 'https://getlasso.co/affiliate/zee-dog/', 'https://getlasso.co/affiliate/zee-dog/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/zee-dog/', 'directory', 'affiliate', 'Lasso''s Zee.Dog program page records an 8% per-sale commission and a 30-day cookie duration for the Zee.Dog affiliate program. No earnings-cap statement is published, so the cap is unknown; no creator count is published, so saturation is unknown.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://olavivo.com/dog-affiliate-programs/', 'directory', 'affiliate', 'Olavivo''s dog affiliate program roundup independently lists Zee.Dog at 8% commission with a 30-day cookie, noting global shipping reach. A Lazada brand wiki for Zee.Dog records the brand facts used here: Brazilian-origin pet lifestyle brand founded in Rio de Janeiro in 2012, official site zeedog.com, wholly owned by Brazilian pet retailer Petz since 2021.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 14, 12, 7, 8, 4, '{"compensation": "A published 8% per sale is mid-range for pet accessories; no cap statement is published", "contact_access": "Directory pages document the program but the hosting network is not named on any fetched page, so the application route needs verification", "credibility": "A global design-led pet brand founded in 2012, owned by Brazil''s largest pet retailer Petz, shipping to 220 countries per published sources", "niche_fit": "Fashion-forward dog accessories are highly visual pet UGC \u2014 matching owner-and-dog looks, walk routines and gear reviews", "opportunity_availability": "Program is live and documented by multiple directories; joining route to be confirmed at application", "ugc_evidence": "Two independent program directories document an active affiliate program, and the brand''s social presence is built around creator-style product content"}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('maxbone', 'https://www.maxbone.com', 'Premium US dog lifestyle brand selling design-led apparel, harnesses, carriers, beds, toys and freeze-dried food. Its own Affiliate Partner Program page runs two tracks — a creator Ambassador program for TikTok, Instagram and YouTube creators and a publisher Affiliate track — with tracking by Impact Radius, monthly payouts, and a published contact email (community@maxbone.com); directory listings record 5% per sale and 5% per subscription order.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'pets'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'partnerships', 'community@maxbone.com', 'https://www.maxbone.com/pages/affiliate-opportunities', 'https://www.maxbone.com/pages/affiliate-opportunities', 'verified', now());
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Impact', 5, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://www.maxbone.com/pages/affiliate-opportunities.', 'https://www.maxbone.com/pages/affiliate-opportunities', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'maxbone Affiliate Partner Program — brand''s own page runs creator ambassador and publisher tracks via Impact, 5% per sale per directory listings', 'https://www.maxbone.com/pages/affiliate-opportunities', 'https://www.maxbone.com/pages/affiliate-opportunities', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.maxbone.com/pages/affiliate-opportunities', 'official_site', 'affiliate', 'maxbone''s own Affiliate Partner Program page fetched in full. For Creators: an ambassador program ''built for influencers and creators who are active on platforms like TikTok, Instagram, or YouTube'', with referral codes and links paying cash commission and higher commission unlocked as earnings grow. For Affiliates: a publisher track with ''Custom third-party tracking by Impact Radius'' and commission for each new customer referred. The page states platforms pay affiliates and ambassadors monthly and publishes the contact ''Email us at community@maxbone.com!''. The page itself does not print the percentage; the rate comes from the directory listing below. No earnings-cap statement is published, so the cap is unknown; no creator count is published, so saturation is unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkclicky.com/affiliate-program/maxbone/', 'directory', 'affiliate', 'LinkClicky''s maxbone program listing records the rate as 5% per sale and 5% per subscription order on the Impact platform; Lasso''s program page independently records 5% per sale with a 7-day cookie.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 16, 10, 13, 9, 4, '{"compensation": "5% per sale and 5% on subscription orders is modest, though the brand states ambassadors unlock higher commission as they earn; no cap statement is published", "contact_access": "Published partnerships email (community@maxbone.com) and an application on the brand''s own program page", "credibility": "An established premium pet lifestyle brand founded in 2015 with national retail distribution", "niche_fit": "Premium, design-led dog products fit style-driven pet UGC \u2014 apparel try-ons, travel gear and home accessories content", "opportunity_availability": "Open applications for both the creator and publisher tracks, tracked on Impact with monthly payouts", "ugc_evidence": "The brand''s own page is built around creators, with a dedicated ambassador track for TikTok, Instagram and YouTube plus product seeding ahead of launches"}'::jsonb);
